SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS `game`;
DROP TABLE IF EXISTS `tournament_user`;
DROP TABLE IF EXISTS `tournaments`;
DROP TABLE IF EXISTS `users`;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE `tournaments`
(
    `id`                  varchar(255) PRIMARY KEY,
    `name`                varchar(255)                         NOT NULL,
    `date`                date                                 NOT NULL,
    `end_date`            date,
    `max_players`         integer                              NOT NULL,
    `country`             varchar(56)                          NOT NULL,
    `city`                varchar(85)                          NOT NULL,
    `zip`                 integer                              NOT NULL,
    `address`             varchar(255)                         NOT NULL,
    `description`         varchar(255),
    `external_link`       varchar(255),
    `orga_id`             varchar(255)                         NOT NULL,
    `state`               ENUM ('created', 'ongoing', 'ended') NOT NULL,
    `current_round`       integer,
    `current_round_state` ENUM ('created', 'ongoing', 'ended'),
    `created_at`          timestamp
);

CREATE TABLE `users`
(
    `id`         varchar(255) PRIMARY KEY,
    `username`   varchar(255) NOT NULL UNIQUE,
    `email`      varchar(255) NOT NULL UNIQUE,
    `password`   varchar(255) NOT NULL,
    `pbw_pin`    varchar(6) UNIQUE,
    `created_at` timestamp
);

CREATE TABLE `game`
(
    `id`            int PRIMARY KEY AUTO_INCREMENT,
    `player1`       varchar(255) NOT NULL,
    `player2`       varchar(255),
    `tournament_id` varchar(255),
    `round_nr`      integer,
    `date`          date         NOT NULL,
    `score1`        integer,
    `score2`        integer,
    `ended`         bool,
    `winner_id`     varchar(255),
    `scenario`      int,
    `table_nr`      int,
    `faction1`      varchar(255) NOT NULL,
    `faction2`      varchar(255)
);

CREATE TABLE `tournament_user`
(
    `id`                      int PRIMARY KEY AUTO_INCREMENT,
    `user_id`                 varchar(255) NOT NULL,
    `tournament_id`           varchar(255) NOT NULL,
    `faction`                 varchar(20)  NOT NULL,
    `has_received_bye`        bool,
    `has_been_paired_up_down` bool,
    `team_name`               varchar(255)
);

ALTER TABLE `tournaments` ADD FOREIGN KEY (`orga_id`) REFERENCES `users` (`id`);
ALTER TABLE `game` ADD FOREIGN KEY (`player1`) REFERENCES `users` (`id`);
ALTER TABLE `game` ADD FOREIGN KEY (`player2`) REFERENCES `users` (`id`);
ALTER TABLE `game` ADD FOREIGN KEY (`tournament_id`) REFERENCES `tournaments` (`id`);
ALTER TABLE `game` ADD FOREIGN KEY (`winner_id`) REFERENCES `users` (`id`);
ALTER TABLE `tournament_user` ADD FOREIGN KEY (`user_id`) REFERENCES `users` (`id`);
ALTER TABLE `tournament_user` ADD FOREIGN KEY (`tournament_id`) REFERENCES `tournaments` (`id`);

