  ('t3_34940', '2. Eroberung der Scheune', '2024-06-08', '2024-06-08', 30, 'Deutschland', 'Bedburg', 50181, 'Clubräume der Bedburger Tabletopfreunde e.V., Meisenweg 1', 'Wir laden euch zu unserem 2. Turnier von Conquest - The Last Argument of Kings ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34940', '87402892fb43851a2c69263acb92fb24c859b40059ec6219038eabfdcbb2ac5e', 'ended', 3, 'ended', '2024-06-08 00:00:00'),
  ('t3_34963', '4. Badisch Conquest', '2024-07-06', '2024-07-06', 24, 'Deutschland', 'March', 79232, 'Feuerwehrhaus March, Sportplatzstraße 20', 'Gespielt werden 3 Runden mit 2000 Punkte nach dem aktuellen Regelwerk. Es gibt offiziellen Preissupport von Para Bellum und vor allem viel Spaß und gute Laune an den Tag. - - - - Played are 3 rounds with 2000 points according to the current rulebook. Ther', 'https://www.tabletopturniere.de/t3_tournament.php?tid=34963', '0d932d61b0fab0181aa877541dbbba044b01dd6e9e442d8533abda4e564ca8e8', 'ended', 3, 'ended', '2024-07-06 00:00:00'),
  ('t3_35935', '1. Drunken Conquest – Last Argument of Dwarfs', '2025-02-01', '2025-02-01', 32, 'Deutschland', 'Duisburg (Germany)', 47229, 'Hobbybunker der Drunken Dwarfs Duisburg, Am Borgschenhof 8', 'Wir laden euch zu unserem 1. Turnier von Conquest - The Last Argument of Kings im Zwergenbunker ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt. We invite you to our first tournament of Conquest - The Last Argument of Kings at the Zwergenbunk', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35935', '8dc7133b09c38be752c70cc3f517ffa2b2e2e8f61c0f4905b41c13fabf3abce8', 'ended', 3, 'ended', '2025-02-01 00:00:00'),
  ('t3_35942', '2. Drunken Conquest – Last Argument of Dwarfs', '2026-03-14', '2026-03-14', 40, 'Deutschland', 'Duisburg (Germany)', 47229, 'Hobbybunker der Drunken Dwarfs Duisburg, Am Borgschenhof 8', 'Wir laden euch zu unserem 2. Turnier von Conquest - The Last Argument of Kings im Zwergenbunker ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt. We invite you to our second tournament of Conquest - The Last Argument of Kings at the Zwergenbun', 'https://www.tabletopturniere.de/t3_tournament.php?tid=35942', '8dc7133b09c38be752c70cc3f517ffa2b2e2e8f61c0f4905b41c13fabf3abce8', 'ended', 3, 'ended', '2026-03-14 00:00:00'),
  ('t3_36006', '5. Badisch Conquest', '2024-11-16', '2024-11-16', 18, 'Deutschland', 'March', 79232, 'Feuerwehrhaus March, Sportplatzstraße 20', 'Gespielt werden 3 Runden mit 2000 Punkte nach dem aktuellen Regelwerk. Es gibt offiziellen Preissupport von Para Bellum und vor allem viel Spaß und gute Laune an den Tag.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36006', '0d932d61b0fab0181aa877541dbbba044b01dd6e9e442d8533abda4e564ca8e8', 'ended', 3, 'ended', '2024-11-16 00:00:00'),
  ('t3_36087', 'Bannerkrieg um Rodenbach "Part 1"', '2025-03-29', '2025-03-29', 12, 'Deutschland', 'Rodenbach', 63517, 'Aleatorium Main-Kinzig e.V., Hanauerstraße 8', 'Unsere Turnier Serie in der Weiten von Eä wird groß und wir wechseln nun auch auf den großen Bruder "Last Argument of Kings"', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36087', '3d35d8958ce2d38c510704ad32f3bbcd06ab2f3e2b2b176a93bcb777e37d8f79', 'ended', 3, 'ended', '2025-03-29 00:00:00'),
  ('t3_36090', 'Bannerkrieg um Rodenbach "Part 2"', '2025-08-30', '2025-08-30', 18, 'Deutschland', 'Rodenbach', 63517, 'Aleatorium Main-Kinzig e.V., Hanauerstraße 8', 'Der zweite Teil unserer "Last Argument of Kings" Turnierserie.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36090', '3d35d8958ce2d38c510704ad32f3bbcd06ab2f3e2b2b176a93bcb777e37d8f79', 'ended', 3, 'ended', '2025-08-30 00:00:00'),
  ('t3_36240', '3. Eroberung der Scheune', '2024-11-30', '2024-11-30', 30, 'Deutschland', 'Bedburg', 50181, 'Clubräume der Bedburger Tabletopfreunde e.V., Meisenweg 1', 'Wir laden euch zu unserem 3. Turnier von Conquest - The Last Argument of Kings ein! Es werden 3 Runden mit einer 2000 Punkte-Liste gespielt.', 'https://www.tabletopturniere.de/t3_tournament.php?tid=36240', '87402892fb43851a2c69263acb92fb24c859b40059ec6219038eabfdcbb2ac5e', 'ended', 3, 'ended', '2024-11-30 00:00:00'),
